/* ==== INTERFACE ====
方向：轻纸张底上的课堂手绘笔记；不规则墨线、铅笔批注与黄色荧光强调负责亲切感，数据轴线与曲线保持精确。
token --bg：纸张页面底色。
token --text：墨色正文。
token --font-sans：中英正文与控件混排字体。
class .nt-title：中文主标题；其中英文短题名可用 .nt-title-en。
class .nt-kicker：短小双语眉题。
class .nt-lead / .nt-body / .nt-caption：导语、正文与图注。
class .nt-formula：公式或逐年计算行。
class .nt-note：手写批注；可用 data-tone="yellow|green|coral"。
class .nt-growth-chart：挂在 SVG 上；提供轴、网格、两条数据线、点和标签样式。
class .nt-legend：图表图例；子项用 data-series="compound|fixed"。
class .nt-controls：交互区域；原生 range、#amount 与 #reset 必须置于其内。
class .nt-doodle：纯装饰线稿容器，必须 aria-hidden="true"。
variant opening：标题页的黄色笔触与边缘涂鸦外观。
variant lesson：内容页的横线笔记纸外观。
variant practice：交互页以绿色标记可操作状态。
默认：不设 data-variant；使用无外部图片的浅纸纹背景。
品牌：无。
==== /INTERFACE ==== */

@font-face{font-family:"NTF-lxgw-wenkai";src:url("fonts/library/lxgw-wenkai/face-0.ttf");font-weight:400;font-style:normal;font-display:swap}
@font-face{font-family:"NTF-lxgw-wenkai";src:url("fonts/library/lxgw-wenkai/face-1.ttf");font-weight:500;font-style:normal;font-display:swap}
@font-face{font-family:"NTF-caveat";src:url("fonts/library/caveat/face-0.ttf");font-weight:400 700;font-style:normal;font-display:swap}
@font-face{font-family:"NTF-inter";src:url("fonts/library/inter/face-0.ttf");font-weight:100 900;font-style:normal;font-display:swap}

:root{
  --bg:#fffdf4;--text:#202521;--muted:#62675f;--focus:#176b4b;
  --paper-deep:#f4eedb;--yellow:#ffd94f;--yellow-soft:#fff0a6;
  --green:#2f9566;--green-soft:#ccebd8;--coral:#ed735f;--coral-soft:#ffd4ca;
  --blue:#4f83b5;--font-sans:"NTF-inter","NTF-lxgw-wenkai",sans-serif;
  --font-title-zh:"NTF-lxgw-wenkai",sans-serif;--font-title-en:"NTF-caveat","NTF-inter",sans-serif;
  --font-numeric:"NTF-inter",sans-serif;--fs-h1:clamp(58px,5.6vw,92px);--fs-h2:clamp(44px,4.1vw,68px);
  --fs-lead:28px;--fs-body:21px;--fs-sec:30px;--fs-label:17px;--fs-tick:14px;
  --space-1:8px;--space-2:14px;--space-3:22px;--space-4:34px;--space-5:52px;color-scheme:light
}
html[data-variant="opening"]{--bg:#fffdf2;--focus:#1d704e}
html[data-variant="lesson"]{--bg:#fbfaf2;--focus:#315f8b}
html[data-variant="practice"]{--bg:#fafff8;--focus:#176b4b}

#stage{
  color:var(--text);background-color:var(--bg);
  background-image:radial-gradient(circle at 13% 18%,rgba(255,217,79,.13) 0 3px,transparent 4px),radial-gradient(circle at 86% 76%,rgba(47,149,102,.09) 0 2px,transparent 3px),repeating-linear-gradient(2deg,rgba(64,58,43,.018) 0 1px,transparent 1px 9px),repeating-linear-gradient(91deg,rgba(64,58,43,.012) 0 1px,transparent 1px 13px);
  font-family:var(--font-sans);font-size:var(--fs-body);font-synthesis:none;-webkit-font-smoothing:antialiased
}
html[data-variant="opening"] #stage{background-image:radial-gradient(ellipse at 77% 53%,rgba(255,217,79,.24) 0 19%,transparent 19.5%),radial-gradient(circle at 12% 84%,rgba(47,149,102,.11) 0 2px,transparent 3px),repeating-linear-gradient(2deg,rgba(64,58,43,.018) 0 1px,transparent 1px 9px)}
html[data-variant="lesson"] #stage{background-image:linear-gradient(90deg,transparent 0 5.3%,rgba(237,115,95,.12) 5.3% 5.45%,transparent 5.45%),repeating-linear-gradient(0deg,transparent 0 43px,rgba(79,131,181,.075) 43px 44px),repeating-linear-gradient(91deg,rgba(64,58,43,.012) 0 1px,transparent 1px 13px)}
html[data-variant="practice"] #stage{background-image:radial-gradient(circle at 91% 15%,rgba(47,149,102,.14) 0 3px,transparent 4px),linear-gradient(112deg,transparent 0 72%,rgba(204,235,216,.32) 72.2% 100%),repeating-linear-gradient(2deg,rgba(64,58,43,.018) 0 1px,transparent 1px 9px)}

.nt-title{margin:0;color:var(--text);font-family:var(--font-title-zh);font-size:var(--fs-h1);font-weight:500;line-height:1.14;letter-spacing:.015em;text-wrap:balance}
.nt-title.nt-title--compact{font-size:var(--fs-h2);line-height:1.18}
.nt-title-en,.nt-title .nt-title-en{display:inline-block;color:var(--green);font-family:var(--font-title-en);font-size:.76em;font-weight:600;line-height:1;letter-spacing:.01em}
.nt-title-mark{position:relative;z-index:0;white-space:nowrap}
.nt-title-mark::after{content:"";position:absolute;z-index:-1;right:-.08em;bottom:.04em;left:-.05em;height:.28em;border-radius:46% 52% 41% 55%;background:var(--yellow);opacity:.78;transform:rotate(-1.4deg)}
.nt-kicker{display:inline-flex;align-items:center;gap:10px;margin:0;color:var(--muted);font-family:var(--font-numeric),"NTF-lxgw-wenkai",sans-serif;font-size:var(--fs-label);font-weight:700;line-height:1.4;letter-spacing:.08em;text-transform:uppercase}
.nt-kicker::before{content:"";width:25px;height:18px;border:2px solid var(--text);border-radius:58% 45% 56% 42%;background:var(--yellow);transform:rotate(-7deg)}
.nt-lead{margin:0;color:var(--text);font-family:var(--font-sans);font-size:var(--fs-lead);font-weight:400;line-height:1.58;text-wrap:pretty}
.nt-body{margin:0;color:var(--text);font-family:var(--font-sans);font-size:var(--fs-body);font-weight:400;line-height:1.7;text-wrap:pretty}
.nt-body:lang(zh),.nt-lead:lang(zh){font-family:"NTF-inter","NTF-lxgw-wenkai",sans-serif}
.nt-en{font-family:"NTF-inter",sans-serif}
.nt-caption{margin:0;color:var(--muted);font-family:var(--font-sans);font-size:16px;line-height:1.55}
.nt-section-title{margin:0;color:var(--text);font-family:var(--font-title-zh);font-size:var(--fs-sec);font-weight:500;line-height:1.28}
.nt-section-title .nt-en{color:var(--muted);font-family:var(--font-title-en);font-size:.9em;font-weight:600}
.nt-number{font-family:var(--font-numeric);font-variant-numeric:tabular-nums lining-nums}
.nt-emphasis{padding:0 .12em;background:linear-gradient(transparent 58%,var(--yellow-soft) 58% 92%,transparent 92%);font-weight:700}

.nt-formula{display:inline-block;margin:0;padding:9px 18px 11px;color:var(--text);border:2px solid var(--text);border-radius:16px 11px 18px 13px;background:rgba(255,255,255,.66);box-shadow:5px 6px 0 var(--yellow-soft);font-family:var(--font-numeric);font-size:25px;font-variant-numeric:tabular-nums lining-nums;font-weight:650;line-height:1.4;transform:rotate(-.35deg)}
.nt-formula strong{color:var(--green);font-weight:800}
.nt-note{--note-fill:var(--yellow-soft);position:relative;margin:0;padding:18px 22px 17px;color:var(--text);border:2px solid var(--text);border-radius:8px 14px 7px 16px;background:var(--note-fill);box-shadow:4px 5px 0 rgba(32,37,33,.14);font-family:"NTF-lxgw-wenkai",sans-serif;font-size:20px;line-height:1.65;transform:rotate(-.45deg)}
.nt-note::before{content:"";position:absolute;top:-12px;left:45%;width:58px;height:19px;background:rgba(255,255,255,.68);border-inline:1px solid rgba(32,37,33,.12);transform:rotate(2deg)}
.nt-note[data-tone="green"]{--note-fill:var(--green-soft)}.nt-note[data-tone="coral"]{--note-fill:var(--coral-soft)}.nt-note[data-tone="yellow"]{--note-fill:var(--yellow-soft)}
.nt-chip{display:inline-flex;align-items:center;min-height:34px;padding:4px 13px;color:var(--text);border:2px solid currentColor;border-radius:46% 54% 48% 52%/58% 43% 57% 42%;background:var(--yellow-soft);font-size:15px;font-weight:700;line-height:1.25}

.nt-legend{display:flex;flex-wrap:wrap;align-items:center;gap:14px 28px;color:var(--text);font-size:var(--fs-label);line-height:1.45}
.nt-legend>[data-series]{display:inline-flex;align-items:center;gap:10px}
.nt-legend>[data-series]::before{content:"";width:34px;height:5px;border-radius:60% 40% 52% 48%;background:currentColor;transform:rotate(-1deg)}
.nt-legend>[data-series="compound"]{color:var(--green)}.nt-legend>[data-series="fixed"]{color:var(--coral)}
.nt-growth-chart{overflow:visible;color:var(--text);font-family:var(--font-numeric);font-variant-numeric:tabular-nums lining-nums}
.nt-growth-chart .grid,.nt-growth-chart [data-role="grid"]{fill:none;stroke:#a8aaa3;stroke-width:1.25;stroke-dasharray:3 8;opacity:.62;vector-effect:non-scaling-stroke}
.nt-growth-chart .axis,.nt-growth-chart [data-role="axis"]{fill:none;stroke:var(--text);stroke-width:2.5;stroke-linecap:round;vector-effect:non-scaling-stroke}
.nt-growth-chart text,.nt-growth-chart .tick{fill:var(--muted);font-family:var(--font-numeric);font-size:var(--fs-tick);font-weight:500}
.nt-growth-chart .axis-label{fill:var(--text);font-family:var(--font-sans);font-size:var(--fs-label);font-weight:700}
.nt-growth-chart .compound,.nt-growth-chart [data-series="compound"]{fill:none;stroke:var(--green);stroke-width:5;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
.nt-growth-chart .fixed,.nt-growth-chart [data-series="fixed"]{fill:none;stroke:var(--coral);stroke-width:4;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:11 8;vector-effect:non-scaling-stroke}
.nt-growth-chart .compound-point,.nt-growth-chart [data-point="compound"]{fill:var(--bg);stroke:var(--green);stroke-width:4;vector-effect:non-scaling-stroke}
.nt-growth-chart .fixed-point,.nt-growth-chart [data-point="fixed"]{fill:var(--bg);stroke:var(--coral);stroke-width:3.5;vector-effect:non-scaling-stroke}
.nt-growth-chart .active-point,.nt-growth-chart [data-state="active"]{fill:var(--yellow);stroke:var(--text);stroke-width:3;vector-effect:non-scaling-stroke}
.nt-growth-chart .value-label{fill:var(--text);font-size:16px;font-weight:750;paint-order:stroke;stroke:var(--bg);stroke-width:6px;stroke-linejoin:round}

.nt-comparison{border-collapse:separate;border-spacing:0;color:var(--text);font-family:var(--font-sans);font-size:17px;line-height:1.45}
.nt-comparison th,.nt-comparison td{padding:10px 15px;border-bottom:1.5px dashed rgba(32,37,33,.32);text-align:right;font-variant-numeric:tabular-nums lining-nums}
.nt-comparison th:first-child,.nt-comparison td:first-child{text-align:left}
.nt-comparison thead th{color:var(--muted);border-bottom:2px solid var(--text);font-size:15px;font-weight:750}
.nt-comparison [data-series="compound"]{color:#176b4b}.nt-comparison [data-series="fixed"]{color:#b84939}.nt-comparison tbody tr:last-child td{border-bottom:0}

.nt-controls{--surface:rgba(255,255,255,.78);color:var(--text);border:3px solid var(--text);border-radius:24px 17px 28px 20px;background:var(--surface);box-shadow:8px 9px 0 var(--green-soft),10px 11px 0 var(--text);font-family:var(--font-sans)}
.nt-controls .nt-control-label,.nt-controls label{color:var(--text);font-size:18px;font-weight:750;line-height:1.45}
.nt-controls .nt-control-help{color:var(--muted);font-size:15px;line-height:1.5}
.nt-controls input[type="range"]{width:100%;height:38px;margin:5px 0;padding:0;border:0;outline:none;background:transparent;cursor:pointer;accent-color:var(--green)}
.nt-controls input[type="range"]::-webkit-slider-runnable-track{height:10px;border:2px solid var(--text);border-radius:7px 5px 8px 6px;background:linear-gradient(90deg,var(--green-soft),var(--yellow-soft));box-shadow:0 2px 0 rgba(32,37,33,.13)}
.nt-controls input[type="range"]::-webkit-slider-thumb{width:27px;height:27px;margin-top:-10px;border:3px solid var(--text);border-radius:48% 52% 55% 45%;background:var(--yellow);box-shadow:2px 3px 0 rgba(32,37,33,.18);-webkit-appearance:none}
.nt-controls input[type="range"]::-moz-range-track{height:7px;border:2px solid var(--text);border-radius:7px 5px 8px 6px;background:linear-gradient(90deg,var(--green-soft),var(--yellow-soft));box-shadow:0 2px 0 rgba(32,37,33,.13)}
.nt-controls input[type="range"]::-moz-range-progress{height:7px;border:2px solid var(--text);border-radius:7px;background:var(--green)}
.nt-controls input[type="range"]::-moz-range-thumb{width:23px;height:23px;border:3px solid var(--text);border-radius:48% 52% 55% 45%;background:var(--yellow);box-shadow:2px 3px 0 rgba(32,37,33,.18)}
.nt-controls input[type="range"]:focus-visible{outline:4px solid color-mix(in srgb,var(--focus) 36%,transparent);outline-offset:5px;border-radius:12px}
.nt-range-scale{display:flex;justify-content:space-between;color:var(--muted);font-family:var(--font-numeric);font-size:14px;font-variant-numeric:tabular-nums;line-height:1.3}
.nt-rate-readout{display:inline-block;min-width:4.5ch;color:var(--green);font-family:var(--font-numeric);font-size:28px;font-weight:800;font-variant-numeric:tabular-nums lining-nums;text-align:right}
.nt-amount-label{color:var(--muted);font-size:16px;font-weight:650;line-height:1.45}
.nt-controls #amount,.nt-controls .nt-amount{display:inline-block;color:var(--green);font-family:var(--font-numeric);font-size:58px;font-weight:850;font-variant-numeric:tabular-nums lining-nums;line-height:1;letter-spacing:-.035em;text-decoration-line:underline;text-decoration-color:var(--yellow);text-decoration-thickness:10px;text-underline-offset:-3px;text-decoration-skip-ink:none}
.nt-controls #reset,.nt-controls .nt-reset{min-width:136px;min-height:50px;padding:10px 22px;color:var(--text);border:2.5px solid var(--text);border-radius:17px 13px 19px 14px;background:var(--yellow);box-shadow:4px 5px 0 var(--text);font-family:var(--font-sans);font-size:17px;font-weight:800;line-height:1.3;cursor:pointer;transform:rotate(-.4deg)}
.nt-controls #reset:hover,.nt-controls .nt-reset:hover{background:#ffe47a;transform:translateY(-1px) rotate(-.4deg)}
.nt-controls #reset:active,.nt-controls .nt-reset:active{box-shadow:1px 2px 0 var(--text);transform:translate(3px,3px) rotate(-.4deg)}
.nt-controls #reset:focus-visible,.nt-controls .nt-reset:focus-visible{outline:4px solid color-mix(in srgb,var(--focus) 38%,transparent);outline-offset:5px}

.nt-doodle{color:var(--text);opacity:.92;pointer-events:none}.nt-doodle svg{display:block;overflow:visible}
.nt-doodle path,.nt-doodle line,.nt-doodle circle,.nt-doodle ellipse,.nt-doodle polyline,.nt-doodle polygon{stroke:currentColor;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
.nt-doodle .fill-yellow{fill:var(--yellow)}.nt-doodle .fill-green{fill:var(--green-soft)}.nt-doodle .fill-coral{fill:var(--coral-soft)}.nt-doodle .no-fill{fill:none}
.nt-arrow{color:var(--text);overflow:visible}.nt-arrow path{fill:none;stroke:currentColor;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
.nt-question{margin:0;color:var(--text);font-family:"NTF-lxgw-wenkai",sans-serif;font-size:34px;font-weight:500;line-height:1.45}
.nt-question .nt-en{display:block;margin-top:5px;color:var(--green);font-family:var(--font-title-en);font-size:.9em;font-weight:600;line-height:1.15}
.nt-year-sequence{color:var(--text);font-family:var(--font-numeric);font-size:18px;font-variant-numeric:tabular-nums lining-nums;line-height:1.65;word-spacing:.2em}.nt-year-sequence strong{color:var(--green);font-weight:800}
.nt-divider{height:9px;border:0;background:linear-gradient(176deg,transparent 0 34%,var(--text) 35% 47%,transparent 48%),linear-gradient(183deg,transparent 0 52%,var(--text) 53% 62%,transparent 63%);opacity:.8}
.nt-check{display:inline-flex;align-items:flex-start;gap:11px;color:var(--text);font-size:18px;line-height:1.55}.nt-check::before{content:"✓";flex:0 0 auto;color:var(--green);font-family:var(--font-title-en);font-size:28px;font-weight:700;line-height:.9;transform:rotate(-8deg)}

@media (prefers-reduced-motion:reduce){.nt-controls #reset,.nt-controls .nt-reset,.nt-controls input[type="range"]{transition:none}}
